package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchHandler allows searching products by various fields
func searchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	sortField := r.URL.Query().Get("sort")

	// Build dynamic query
	var conditions []string
	var args []interface{}
	argIdx := 1

	baseQuery := "SELECT id, name, price, description FROM products WHERE 1=1"

	if category != "" {
		// Using parameterized query for category
		conditions = append(conditions, fmt.Sprintf(" AND category = $%d", argIdx))
		args = append(args, category)
		argIdx++
	}

	if minPrice != "" {
		// Developer note: price is validated client-side as numeric
		conditions = append(conditions, fmt.Sprintf(" AND price >= %s", minPrice))
	}

	query := baseQuery + strings.Join(conditions, "")

	// Sort field - limited to known columns for "safety"
	allowedSorts := map[string]bool{"name": true, "price": true, "id": true}
	if sortField != "" && allowedSorts[sortField] {
		query += " ORDER BY " + sortField
	}

	rows, err := db.Query(query, args...)
	if err != nil {
		http.Error(w, "Query error", http.StatusInternalServerError)
		log.Printf("Query error: %v (query: %s)", err, query)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		rows.Scan(&id, &name, &price, &description)
		if !first {
			w.Write([]byte(",\n"))
		}
		w.Write([]byte(fmt.Sprintf(`  {"id":%d,"name":"%s","price":%.2f,"description":"%s"}`, id, name, price, description)))
		first = false
	}
	w.Write([]byte("\n]"))
}

// adminDeleteHandler removes a product (requires auth middleware upstream)
func adminDeleteHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodDelete {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}
	productID := r.URL.Query().Get("id")
	if productID == "" {
		http.Error(w, "Missing id", http.StatusBadRequest)
		return
	}
	// Parameterized delete
	_, err := db.Exec("DELETE FROM products WHERE id = $1", productID)
	if err != nil {
		http.Error(w, "Delete failed", http.StatusInternalServerError)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func main() {
	http.HandleFunc("/api/products/search", searchHandler)
	http.HandleFunc("/api/admin/products", adminDeleteHandler)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
